// Standard Nextruder heater replacement, adapted from official Prusa guide 944862.
const CONTENT={"id":"hotend-heater","revision":1,"category":1,"title":["ホットエンドのヒーターを交換する","Replace the hotend heater","Výměna topení hotendu","Hotend-Heizpatrone austauschen"],"interval":["交換が必要なとき","When replacement is needed","Při potřebě výměny","Bei erforderlichem Austausch"],"source":"https://help.prusa3d.com/guide/how-to-replace-a-hotend-heater-core-one_944862","steps":[{"title":["ホットエンドのヒーターだけを交換する","Replace only the hotend heater","Vyměnit pouze topení hotendu","Nur Hotend-Heizpatrone austauschen"],"body":["標準Nextruderのヒーター単体交換です。ブロックとノズル、サーミスターは再使用します。まずホットエンドを冷却して取り外します。HT Hotendなど別構成は専用ガイドで確認します。","This replaces the heater in the standard Nextruder hotend. Reuse the block, nozzle and thermistor. First cool and remove the hotend. Other configurations such as HT Hotend have dedicated guides.","Výměna topení standardního hotendu Nextruder. Blok, trysku a termistor znovu použijete. Nejprve hotend ochlaďte a vyjměte. Jiné konfigurace, například HT Hotend, mají vlastní návody.","Austausch der Heizpatrone im Standard-Nextruder-Hotend. Block, Düse und Thermistor werden weiterverwendet. Hotend zuerst abkühlen und ausbauen. Für andere Ausführungen wie HT Hotend gelten eigene Anleitungen."],"refs":["hotend"],"componentAccessIndex":0,"id":"heater-944923","officialId":944923,"officialStep":1,"source":"https://help.prusa3d.com/guide/how-to-replace-a-hotend-heater-core-one_944862#944923","sourcePhotos":[{"url":"https://help.prusa3d.com/wp-content/uploads/2025/09/95d25ccc7bf1e946ec2ba31a4f485e5b-800x600.jpg","full":"https://help.prusa3d.com/wp-content/uploads/2025/09/95d25ccc7bf1e946ec2ba31a4f485e5b-800x600.jpg","credit":["写真：Prusa Research","Photo: Prusa Research","Fotografie: Prusa Research","Foto: Prusa Research"]},{"url":"https://help.prusa3d.com/wp-content/uploads/2023/11/1e200fcb512a03e4e0a4d47ee869ae60-800x600.jpg","full":"https://help.prusa3d.com/wp-content/uploads/2023/11/1e200fcb512a03e4e0a4d47ee869ae60-800x600.jpg","credit":["写真：Prusa Research","Photo: Prusa Research","Fotografie: Prusa Research","Foto: Prusa Research"]}]},{"title":["工具と交換部品を準備する","Prepare tools and replacement parts","Připravit nářadí a náhradní díly","Werkzeug und Ersatzteile vorbereiten"],"body":["2.5 mm六角レンチ、T6キー、T10キー／ドライバーを用意します。T6で扱うのは、図のヒーター固定ねじ2本です。ブロックのサーミスター固定ねじは緩めず、ノズルをブロックからねじ外しません。","Prepare a 2.5 mm Allen key, T6 key and T10 key/driver. Use T6 on the two indicated heater screws. Leave the block’s thermistor retaining screw alone and do not unscrew the nozzle from the block.","Připravte 2,5mm imbus, klíč T6 a T10. T6 použijte na dva označené šrouby topení. Stavěcí šroub termistoru v bloku nepovolujte a trysku z bloku nevyšroubovávejte.","2,5-mm-Inbus, T6 und T10 bereitlegen. T6 an den zwei gezeigten Heizungsschrauben verwenden. Thermistor-Gewindestift im Block nicht lösen und Düse nicht aus dem Block schrauben."],"refs":["hotend"],"componentAccessIndex":1,"id":"heater-944966","officialId":944966,"officialStep":2,"source":"https://help.prusa3d.com/guide/how-to-replace-a-hotend-heater-core-one_944862#944966","sourcePhotos":[{"url":"https://help.prusa3d.com/wp-content/uploads/2025/09/fb2e7fe26232d057ff5a5112723c8b92_painted-800x600.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/09/fb2e7fe26232d057ff5a5112723c8b92_painted-800x600.jpeg","credit":["写真：Prusa Research","Photo: Prusa Research","Fotografie: Prusa Research","Foto: Prusa Research"]}]},{"title":["フィラメントを抜き、冷却する","Unload and cool down","Vyjmutí filamentu a chlazení","Entladen und abkühlen"],"body":["ドアを閉じます。画面のFilament → Unload filamentでフィラメントをアンロードし、スプールを外します。Preheat → COOLDOWNを選び、プリンターが室温まで冷えるのを待ちます。温度エラーやアンロード失敗時は、加熱や強い引き抜きを繰り返さず、公式サポートへ進んでください。","Close the door. Use Filament → Unload filament to unload, then remove the spool. Select Preheat → COOLDOWN and wait until the printer reaches ambient temperature. If a temperature error occurs or unloading fails, do not repeatedly heat or pull forcefully; contact official support.","Zavřete dvířka. V nabídce Filament → Unload filament vysuňte filament a sejměte cívku. Zvolte Preheat → COOLDOWN a vyčkejte na pokojovou teplotu tiskárny. Při teplotní chybě nebo neúspěšném vysunutí neopakujte ohřev ani netahejte silou; obraťte se na oficiální podporu.","Tür schließen. Filament über Filament → Unload filament entladen und die Spule abnehmen. Preheat → COOLDOWN wählen und auf Raumtemperatur abkühlen lassen. Bei Temperaturfehler oder fehlgeschlagenem Entladen nicht wiederholt heizen oder kräftig ziehen, sondern den offiziellen Support kontaktieren."],"refs":["lcd"],"firmwareActions":["unload","cooldown"],"componentAccessIndex":2,"id":"heater-945000","officialId":945000,"officialStep":3,"source":"https://help.prusa3d.com/guide/how-to-replace-a-hotend-heater-core-one_944862#945000","sourcePhotos":[{"url":"https://help.prusa3d.com/wp-content/uploads/2025/09/efa028e51e5730e81f008240fe3fd9aa_painted-800x600.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/09/efa028e51e5730e81f008240fe3fd9aa_painted-800x600.jpeg","credit":["写真：Prusa Research","Photo: Prusa Research","Fotografie: Prusa Research","Foto: Prusa Research"]},{"url":"https://help.prusa3d.com/wp-content/uploads/2025/09/5b2b98da0c121a52ef300ab8805ac389_painted-800x600.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/09/5b2b98da0c121a52ef300ab8805ac389_painted-800x600.jpeg","credit":["写真：Prusa Research","Photo: Prusa Research","Fotografie: Prusa Research","Foto: Prusa Research"]},{"url":"https://help.prusa3d.com/wp-content/uploads/2025/09/36a965597b3f1dadc4808a40356171b4_painted-800x600.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/09/36a965597b3f1dadc4808a40356171b4_painted-800x600.jpeg","credit":["写真：Prusa Research","Photo: Prusa Research","Fotografie: Prusa Research","Foto: Prusa Research"]}]},{"title":["ベッドを下げ、電源を外す","Lower the bed and unplug","Snížení podložky a odpojení","Heizbett absenken und Netzstecker ziehen"],"body":["Control → Move Axis → Move Zを100 mm以上にします。ベッドが下がって停止してから背面スイッチを切り、電源コードを抜きます。","Set Control → Move Axis → Move Z to at least 100 mm. Wait for the bed to stop, then switch off at the rear and unplug.","Nastavte Control → Move Axis → Move Z alespoň na 100 mm. Počkejte na zastavení podložky, pak vypněte zadní vypínač a odpojte napájení.","Control → Move Axis → Move Z auf mindestens 100 mm stellen. Stillstand des Heizbetts abwarten, dann hinten ausschalten und Netzstecker ziehen."],"refs":["heatbed","psu"],"firmwareActions":["moveZ"],"componentAccessIndex":3,"id":"heater-945062","officialId":945062,"officialStep":4,"source":"https://help.prusa3d.com/guide/how-to-replace-a-hotend-heater-core-one_944862#945062","sourcePhotos":[{"url":"https://help.prusa3d.com/wp-content/uploads/2025/09/9b4f44d05b828cea18c42ec79efe0b25_painted-800x600.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/09/9b4f44d05b828cea18c42ec79efe0b25_painted-800x600.jpeg","credit":["写真：Prusa Research","Photo: Prusa Research","Fotografie: Prusa Research","Foto: Prusa Research"]},{"url":"https://help.prusa3d.com/wp-content/uploads/2025/09/efa028e51e5730e81f008240fe3fd9aa_painted-800x600.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/09/efa028e51e5730e81f008240fe3fd9aa_painted-800x600.jpeg","credit":["写真：Prusa Research","Photo: Prusa Research","Fotografie: Prusa Research","Foto: Prusa Research"]},{"url":"https://help.prusa3d.com/wp-content/uploads/2025/09/8fe86cf7ce0f65358a5dc6223bed4137_painted-800x600.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/09/8fe86cf7ce0f65358a5dc6223bed4137_painted-800x600.jpeg","credit":["写真：Prusa Research","Photo: Prusa Research","Fotografie: Prusa Research","Foto: Prusa Research"]}]},{"title":["トップカバーを外す","Remove the top cover","Sejmutí horního krytu","Obere Abdeckung abnehmen"],"body":["ドアを開け、内側からトップカバー右前のナイロンリベットを押してロックを外します。外側からそのリベットを抜き、残りも同じ方法で外して保管します。トップカバーを持ち上げて外します。","Open the door. From inside, push the front-right top-cover nylon rivet to unlock it, then remove it from outside. Remove and retain the remaining rivets the same way, then lift off the top cover.","Otevřete dvířka. Zevnitř vytlačte nylonový nýt v pravém předním rohu horního krytu, abyste jej odjistili, a zvenku jej vyjměte. Stejně vyjměte a uschovejte ostatní nýty a sejměte horní kryt.","Tür öffnen. Den Nylon-Niet vorne rechts an der oberen Abdeckung von innen zum Entriegeln herausdrücken und von außen abnehmen. Die übrigen Niete ebenso herausnehmen und aufbewahren, dann die obere Abdeckung abheben."],"refs":["top"],"action":"top-out","componentAccessIndex":4,"id":"heater-945108","officialId":945108,"officialStep":5,"source":"https://help.prusa3d.com/guide/how-to-replace-a-hotend-heater-core-one_944862#945108","sourcePhotos":[{"url":"https://help.prusa3d.com/wp-content/uploads/2025/09/6e264363eeed86ac9b007f839e46e774_painted-800x600.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/09/6e264363eeed86ac9b007f839e46e774_painted-800x600.jpeg","credit":["写真：Prusa Research","Photo: Prusa Research","Fotografie: Prusa Research","Foto: Prusa Research"]},{"url":"https://help.prusa3d.com/wp-content/uploads/2025/09/f8b6d63d8fe9b903245834802d1d84e0_painted-800x600.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/09/f8b6d63d8fe9b903245834802d1d84e0_painted-800x600.jpeg","credit":["写真：Prusa Research","Photo: Prusa Research","Fotografie: Prusa Research","Foto: Prusa Research"]},{"url":"https://help.prusa3d.com/wp-content/uploads/2025/09/5cc4c01ca4e63a55df8719743fb79700_painted-800x600.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/09/5cc4c01ca4e63a55df8719743fb79700_painted-800x600.jpeg","credit":["写真：Prusa Research","Photo: Prusa Research","Fotografie: Prusa Research","Foto: Prusa Research"]}]},{"title":["ベッドを保護する","Protect the bed","Ochrana podložky","Heizbett schützen"],"body":["厚みのある布などでベッドを覆います。","Cover the bed with protective fabric.","Podložku překryjte ochrannou látkou.","Heizbett mit schützendem Stoff abdecken."],"refs":["heatbed"],"componentAccessIndex":5,"id":"heater-945154","officialId":945154,"officialStep":6,"source":"https://help.prusa3d.com/guide/how-to-replace-a-hotend-heater-core-one_944862#945154","sourcePhotos":[{"url":"https://help.prusa3d.com/wp-content/uploads/2025/09/e957b5b0c5b0155d1239198bbc3f82ec_painted-800x600.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/09/e957b5b0c5b0155d1239198bbc3f82ec_painted-800x600.jpeg","credit":["写真：Prusa Research","Photo: Prusa Research","Fotografie: Prusa Research","Foto: Prusa Research"]}]},{"title":["左カバーを外す","Remove the left cover","Sejmutí levého krytu","Linke Abdeckung abnehmen"],"body":["上側のM3x10を2.5 mm六角レンチで外し、左カバーを外します。初期型はM3x10bTが2本の場合があるため、T10で両方を外します。実機のネジを公式写真と照合してください。","Remove the upper M3x10 with a 2.5 mm hex key, then the left cover. Early printers may have two M3x10bT screws; remove both with T10. Match the actual screws to the official photos.","Vyjměte horní M3x10 pomocí 2,5mm imbusu a sejměte levý kryt. Rané tiskárny mohou mít dva M3x10bT; oba vyjměte pomocí T10. Šrouby porovnejte s oficiálními fotografiemi.","Obere M3x10 mit 2,5-mm-Innensechskant lösen und linke Abdeckung abnehmen. Frühe Drucker können zwei M3x10bT haben; beide mit T10 entfernen. Schrauben mit den offiziellen Fotos vergleichen."],"refs":[858],"action":"cover-out","componentAccessIndex":6,"id":"heater-945180","officialId":945180,"officialStep":7,"source":"https://help.prusa3d.com/guide/how-to-replace-a-hotend-heater-core-one_944862#945180","sourcePhotos":[{"url":"https://help.prusa3d.com/wp-content/uploads/2025/09/a459c973528d266f_painted-800x600.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/09/a459c973528d266f_painted-800x600.jpeg","credit":["写真：Prusa Research","Photo: Prusa Research","Fotografie: Prusa Research","Foto: Prusa Research"]},{"url":"https://help.prusa3d.com/wp-content/uploads/2025/09/79bbed01d60740c2a8538fb99e08754a_painted-800x600.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/09/79bbed01d60740c2a8538fb99e08754a_painted-800x600.jpeg","credit":["写真：Prusa Research","Photo: Prusa Research","Fotografie: Prusa Research","Foto: Prusa Research"]}]},{"title":["ヒーターとサーミスターを抜く","Disconnect heater and thermistor","Odpojení topení a termistoru","Heizung und Thermistor abstecken"],"body":["ラッチを押してヒーター、サーミスターの順に抜きます。端子や細い配線を引っ張らないでください。","Release the latches; unplug the heater, then the thermistor. Do not pull on terminals or thin wires.","Uvolněte západky; odpojte topení a potom termistor. Netahejte za kontakty ani tenké vodiče.","Verriegelungen lösen; Heizung, dann Thermistor abziehen. Nicht an Kontakten oder dünnen Leitungen ziehen."],"refs":["loveBoard",857],"action":"unplug","componentAccessIndex":7,"id":"heater-945216","officialId":945216,"officialStep":8,"source":"https://help.prusa3d.com/guide/how-to-replace-a-hotend-heater-core-one_944862#945216","sourcePhotos":[{"url":"https://help.prusa3d.com/wp-content/uploads/2025/09/0b5dc324172c7faf_painted-800x600.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/09/0b5dc324172c7faf_painted-800x600.jpeg","credit":["写真：Prusa Research","Photo: Prusa Research","Fotografie: Prusa Research","Foto: Prusa Research"]},{"url":"https://help.prusa3d.com/wp-content/uploads/2025/09/eab0eff9ec129209179f0c6cf2b255ac_painted-800x600.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/09/eab0eff9ec129209179f0c6cf2b255ac_painted-800x600.jpeg","credit":["写真：Prusa Research","Photo: Prusa Research","Fotografie: Prusa Research","Foto: Prusa Research"]},{"url":"https://help.prusa3d.com/wp-content/uploads/2025/09/1404d57066bc70d0_painted-800x600.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/09/1404d57066bc70d0_painted-800x600.jpeg","credit":["写真：Prusa Research","Photo: Prusa Research","Fotografie: Prusa Research","Foto: Prusa Research"]}]},{"title":["ホットエンドを引き抜く","Withdraw the hotend","Vyjmutí hotendu","Hotend herausziehen"],"body":["ケーブルをガイドから外します。落下しないようホットエンドを片手で支え、もう片方の手でつまみネジ2本を数回転緩めます。ネジは抜き切りません。ホットエンドを下へ引き抜きます。","Free the cables from the guide. Hold the hotend to prevent it falling; loosen both thumbscrews a few turns with the other hand. Leave the screws in place and withdraw the hotend downward.","Uvolněte kabely z vedení. Hotend držte proti pádu a druhou rukou povolte oba ruční šrouby o několik otáček. Šrouby nevyjímejte; hotend vytáhněte dolů.","Kabel aus der Führung nehmen. Hotend gegen Herabfallen halten und beide Rändelschrauben mit der anderen Hand einige Umdrehungen lösen. Schrauben nicht ganz herausdrehen; Hotend nach unten herausziehen."],"refs":["hotend",795,807],"action":"hotend-out","componentAccessIndex":8,"id":"heater-945254","officialId":945254,"officialStep":9,"source":"https://help.prusa3d.com/guide/how-to-replace-a-hotend-heater-core-one_944862#945254","sourcePhotos":[{"url":"https://help.prusa3d.com/wp-content/uploads/2025/09/12b87afb8415cb4d3a2f6bd27fd56ea0_painted-800x600.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/09/12b87afb8415cb4d3a2f6bd27fd56ea0_painted-800x600.jpeg","credit":["写真：Prusa Research","Photo: Prusa Research","Fotografie: Prusa Research","Foto: Prusa Research"]},{"url":"https://help.prusa3d.com/wp-content/uploads/2025/09/8d525f7f932eb781_painted-800x600.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/09/8d525f7f932eb781_painted-800x600.jpeg","credit":["写真：Prusa Research","Photo: Prusa Research","Fotografie: Prusa Research","Foto: Prusa Research"]},{"url":"https://help.prusa3d.com/wp-content/uploads/2025/09/4c555632af97504560d10e78fa5e8232_painted-800x600.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/09/4c555632af97504560d10e78fa5e8232_painted-800x600.jpeg","credit":["写真：Prusa Research","Photo: Prusa Research","Fotografie: Prusa Research","Foto: Prusa Research"]}]},{"title":["使用中のソックを外す","Remove the fitted sock","Sejmout používaný návlek","Montierte Socke abnehmen"],"body":["室温まで冷えたホットエンドを支え、装着されている場合だけシリコンソックを外します。ブロックを配線でつり下げません。","Support the room-temperature hotend and remove the silicone sock only if fitted. Do not suspend the block by its wires.","Podepřete hotend vychladlý na pokojovou teplotu a sejměte silikonový návlek, je-li nasazen. Blok nezavěšujte za vodiče.","Auf Raumtemperatur abgekühltes Hotend stützen und Silikonsocke nur falls vorhanden abnehmen. Block nicht an Leitungen hängen lassen."],"refs":["serviceSock"],"componentMode":"sock-out","id":"heater-945849","officialId":945849,"officialStep":10,"source":"https://help.prusa3d.com/guide/how-to-replace-a-hotend-heater-core-one_944862#945849","sourcePhotos":[{"url":"https://help.prusa3d.com/wp-content/uploads/2025/09/9c834ef8b3348dfa_painted-800x600.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/09/9c834ef8b3348dfa_painted-800x600.jpeg","credit":["写真：Prusa Research","Photo: Prusa Research","Fotografie: Prusa Research","Foto: Prusa Research"]}]},{"title":["T6で緩め、ヒーターを抜く","Loosen with T6 and remove the heater","Povolit T6 a vyjmout topení","Mit T6 lösen und Heizpatrone herausziehen"],"body":["室温まで冷えたブロックを支え、図のヒーター固定ねじ2本をT6で1本ずつ緩め、ヒーターを抜きます。新しい2本に交換するため、元の止めねじも外して分けておきます。サーミスターとノズルは付けたままです。配線をつかんで引き抜かないでください。","Support the block at room temperature. Loosen the two indicated heater screws one at a time with T6 and withdraw the heater. Remove and set aside the old grub screws for replacement by the new pair. Leave the thermistor and nozzle fitted; do not pull on the wires.","Podepřete blok vychladlý na pokojovou teplotu. T6 postupně povolte oba označené šrouby a vyjměte topení. Staré stavěcí šrouby vyjměte a odložte pro výměnu za nové. Termistor a trysku ponechte namontované; netahejte za vodiče.","Auf Raumtemperatur abgekühlten Block stützen. Die zwei gezeigten Schrauben mit T6 einzeln lösen und Heizpatrone herausnehmen. Alte Gewindestifte zur Erneuerung herausnehmen und getrennt ablegen. Thermistor und Düse bleiben montiert; nicht an Leitungen ziehen."],"refs":["heaterServiceCartridge","serviceBlock"],"componentMode":"heater-out","id":"heater-945693","officialId":945693,"officialStep":11,"source":"https://help.prusa3d.com/guide/how-to-replace-a-hotend-heater-core-one_944862#945693","sourcePhotos":[{"url":"https://help.prusa3d.com/wp-content/uploads/2023/11/8005a44da52cb5a6e4092ef7ff01e98e_painted-800x600.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2023/11/8005a44da52cb5a6e4092ef7ff01e98e_painted-800x600.jpeg","credit":["写真：Prusa Research","Photo: Prusa Research","Fotografie: Prusa Research","Foto: Prusa Research"]},{"url":"https://help.prusa3d.com/wp-content/uploads/2023/11/d99d8e812f55f4150761ec0aea5875a5_painted-800x600.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2023/11/d99d8e812f55f4150761ec0aea5875a5_painted-800x600.jpeg","credit":["写真：Prusa Research","Photo: Prusa Research","Fotografie: Prusa Research","Foto: Prusa Research"]},{"url":"https://help.prusa3d.com/wp-content/uploads/2023/11/ba73e47a9e99b035b1bc459dac19ce4a_painted-800x600.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2023/11/ba73e47a9e99b035b1bc459dac19ce4a_painted-800x600.jpeg","credit":["写真：Prusa Research","Photo: Prusa Research","Fotografie: Prusa Research","Foto: Prusa Research"]}]},{"title":["新しいヒーターと固定ねじを確認する","Check the new heater and screws","Zkontrolovat nové topení a šrouby","Neue Heizpatrone und Schrauben prüfen"],"body":["新しいホットエンドヒーター1個と、新しいM3x4bT止めねじ2本を用意します。ヒートシンクのNTC固定ねじとは区別します。","Prepare one new hotend heater and two new M3x4bT grub screws. Distinguish these from the heatsink NTC retaining screw.","Připravte nové topení hotendu a dva nové stavěcí šrouby M3x4bT. Nezaměňujte je se šroubem NTC chladiče.","Eine neue Hotend-Heizpatrone und zwei neue M3x4bT-Gewindestifte bereitlegen. Nicht mit der Halteschraube des Kühlkörper-NTC verwechseln."],"refs":["heaterServiceCartridge"],"componentMode":"heater-prep","id":"heater-945717","officialId":945717,"officialStep":12,"source":"https://help.prusa3d.com/guide/how-to-replace-a-hotend-heater-core-one_944862#945717","sourcePhotos":[{"url":"https://help.prusa3d.com/wp-content/uploads/2023/11/9ce1dd41848e645f945e5ca4187e96e4_painted-800x600.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2023/11/9ce1dd41848e645f945e5ca4187e96e4_painted-800x600.jpeg","credit":["写真：Prusa Research","Photo: Prusa Research","Fotografie: Prusa Research","Foto: Prusa Research"]}]},{"title":["底面をそろえて固定する","Align the bottoms and secure","Zarovnat spodní plochy a zajistit","Unterseiten ausrichten und befestigen"],"body":["新しい止めねじをT6で少しだけねじ込み、ヒーターを奥まで差し込みます。ヒーターとブロックの底面をそろえ、位置を保ちながらT6の長い側で2本をやさしく締めます。締め過ぎず、使っていたソックを戻します。","Start the new grub screws loosely with T6, then insert the heater fully. Align the heater bottom with the block bottom. Hold that position and gently tighten both screws using the long side of T6. Do not overtighten; refit the sock if used.","Nové šrouby lehce zašroubujte T6 a topení zasuňte nadoraz. Zarovnejte spodní plochu topení s blokem. Polohu držte a dlouhou stranou T6 jemně utáhněte oba šrouby. Nepřetahujte; vraťte používaný návlek.","Neue Gewindestifte mit T6 lose ansetzen, Heizpatrone ganz einschieben und Unterseiten von Patrone und Block ausrichten. Position halten und beide Schrauben mit der langen T6-Seite behutsam anziehen. Nicht überdrehen; verwendete Socke wieder montieren."],"refs":["heaterServiceCartridge","serviceBlock","serviceSock"],"componentMode":"heater-in","id":"heater-945765","officialId":945765,"officialStep":13,"source":"https://help.prusa3d.com/guide/how-to-replace-a-hotend-heater-core-one_944862#945765","sourcePhotos":[{"url":"https://help.prusa3d.com/wp-content/uploads/2023/11/e091199e5a0aa96659cbf5b8c1b4cbf3_painted-800x600.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2023/11/e091199e5a0aa96659cbf5b8c1b4cbf3_painted-800x600.jpeg","credit":["写真：Prusa Research","Photo: Prusa Research","Fotografie: Prusa Research","Foto: Prusa Research"]},{"url":"https://help.prusa3d.com/wp-content/uploads/2023/11/c65155726e56998a5cc2d17ef835fc0f_painted-800x600.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2023/11/c65155726e56998a5cc2d17ef835fc0f_painted-800x600.jpeg","credit":["写真：Prusa Research","Photo: Prusa Research","Fotografie: Prusa Research","Foto: Prusa Research"]},{"url":"https://help.prusa3d.com/wp-content/uploads/2025/09/9c834ef8b3348dfa_painted-800x600.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/09/9c834ef8b3348dfa_painted-800x600.jpeg","credit":["写真：Prusa Research","Photo: Prusa Research","Fotografie: Prusa Research","Foto: Prusa Research"]}]},{"title":["奥まで押し込み、固定する","Insert fully and secure","Úplné zasunutí a upevnění","Ganz einschieben und sichern"],"body":["ケーブルを少し前へ向け、下からヒートシンクの奥まで差します。ホットエンド一式がファンシュラウドのくぼみに適切な隙間を残して収まり、その下へ突き出さないことを公式写真で確認します。上へ押し続けながら両方のつまみネジを締めます。","Angle the cables slightly forward and insert fully into the heatsink from below. Match the photo: the assembly must fit the fan-shroud recess with clearance and must not protrude below the shroud. Keep pushing upward while tightening both thumbscrews.","Kabely natočte mírně dopředu a hotend zasuňte zespodu nadoraz do chladiče. Podle fotografie ověřte usazení ve vybrání krytu ventilátoru s vůlí, bez vyčnívání pod kryt. Při utahování obou ručních šroubů tlačte vzhůru.","Kabel leicht nach vorne richten und Hotend von unten ganz in den Kühlkörper einschieben. Mit dem Foto vergleichen: Die Baugruppe muss mit Spiel in der Aussparung des Lüfterkanals sitzen und darf nicht darunter hervorstehen. Beim Anziehen beider Rändelschrauben weiter nach oben drücken."],"refs":["hotend",795,807],"action":"hotend-in","componentAccessIndex":10,"id":"heater-945308","officialId":945308,"officialStep":14,"source":"https://help.prusa3d.com/guide/how-to-replace-a-hotend-heater-core-one_944862#945308","sourcePhotos":[{"url":"https://help.prusa3d.com/wp-content/uploads/2025/09/82142058758e5141e25ec731938830de_painted-800x600.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/09/82142058758e5141e25ec731938830de_painted-800x600.jpeg","credit":["写真：Prusa Research","Photo: Prusa Research","Fotografie: Prusa Research","Foto: Prusa Research"]},{"url":"https://help.prusa3d.com/wp-content/uploads/2025/09/8d525f7f932eb781_painted-800x600.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/09/8d525f7f932eb781_painted-800x600.jpeg","credit":["写真：Prusa Research","Photo: Prusa Research","Fotografie: Prusa Research","Foto: Prusa Research"]},{"url":"https://help.prusa3d.com/wp-content/uploads/2025/09/ac0c50745d0c0a73_painted-800x600.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/09/ac0c50745d0c0a73_painted-800x600.jpeg","credit":["写真：Prusa Research","Photo: Prusa Research","Fotografie: Prusa Research","Foto: Prusa Research"]}]},{"title":["差し込み位置を確認する","Check full insertion","Zkontrolovat úplné zasunutí","Vollständiges Einstecken prüfen"],"body":["このガイドでは、正しく入った銅色リングは見えないとされています。公式の接写と、ファンシュラウド下へ突出しない位置を照合します。修正する場合は両つまみねじを緩め、上へ押し続けて締め直します。","This guide describes the copper ring as not visible when correctly seated. Compare its close-up and the position above the fan shroud. To adjust, loosen both thumbscrews, keep pushing upward and retighten.","Tento návod popisuje při správném zasunutí neviditelný měděný kroužek. Porovnejte detail a polohu nad krytem ventilátoru. Při úpravě povolte oba ruční šrouby, tlačte vzhůru a znovu utáhněte.","Diese Anleitung beschreibt einen bei korrektem Sitz nicht sichtbaren Kupferring. Mit Nahaufnahme und Lage oberhalb der Lüfterhaube vergleichen. Zur Korrektur beide Rändelschrauben lösen, weiter nach oben drücken und festziehen."],"refs":["hotend"],"componentAccessIndex":11,"id":"heater-945363","officialId":945363,"officialStep":15,"source":"https://help.prusa3d.com/guide/how-to-replace-a-hotend-heater-core-one_944862#945363","sourcePhotos":[{"url":"https://help.prusa3d.com/wp-content/uploads/2025/09/0eeae9c38385849a_painted-800x600.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/09/0eeae9c38385849a_painted-800x600.jpeg","credit":["写真：Prusa Research","Photo: Prusa Research","Fotografie: Prusa Research","Foto: Prusa Research"]}]},{"title":["ケーブルをガイドへ戻す","Route the cables","Vedení kabelů","Kabel führen"],"body":["つまみネジの後ろにある樹脂フックの溝へ、サーミスター、ヒーターの順に通します。","Use the channel in the plastic hook behind the thumbscrews: thermistor cable first, then heater cable.","Do drážky plastového háčku za ručními šrouby veďte nejprve kabel termistoru, potom topení.","In der Nut des Kunststoffhakens hinter den Rändelschrauben zuerst das Thermistorkabel, dann das Heizkabel führen."],"refs":[857,"hotend"],"action":"route-hotend","componentAccessIndex":12,"id":"heater-945397","officialId":945397,"officialStep":16,"source":"https://help.prusa3d.com/guide/how-to-replace-a-hotend-heater-core-one_944862#945397","sourcePhotos":[{"url":"https://help.prusa3d.com/wp-content/uploads/2025/09/12b87afb8415cb4d3a2f6bd27fd56ea0_painted-800x600.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/09/12b87afb8415cb4d3a2f6bd27fd56ea0_painted-800x600.jpeg","credit":["写真：Prusa Research","Photo: Prusa Research","Fotografie: Prusa Research","Foto: Prusa Research"]}]},{"title":["LoveBoardへ接続する","Reconnect to LoveBoard","Připojení k LoveBoard","Wieder mit LoveBoard verbinden"],"body":["サーミスターをLoveBoard左側の一番上のNT端子へ、次にヒーターを基板上部の黒いHEATER端子へ接続します。公式写真と基板表示を照合してください。 コネクターのラッチと差し込み向きを合わせ、無理に逆向きへ押し込まないでください。端子や配線の位置は入れ替えません。","Connect the thermistor to NT at the top left of LoveBoard, then the heater to the black HEATER socket at the top. Match the official photo and board labels. Align each connector and its latch; never force it in backwards. Do not exchange terminals or wire positions.","Připojte termistor do NT vlevo nahoře na LoveBoard, potom topení do černého HEATER nahoře. Ověřte podle oficiální fotografie a popisků desky. Srovnejte konektor a západku; opačně jej nevtlačujte silou. Pozice kontaktů ani vodičů nezaměňujte.","Thermistor an NT oben links am LoveBoard anschließen, dann Heizung an die schwarze HEATER-Buchse oben. Mit offiziellem Foto und Platinenbeschriftung abgleichen. Stecker und Verriegelung richtig ausrichten; nicht verkehrt herum erzwingen. Kontakte und Leitungspositionen nicht vertauschen."],"refs":["loveBoard"],"action":"plug","componentAccessIndex":13,"id":"heater-945415","officialId":945415,"officialStep":17,"source":"https://help.prusa3d.com/guide/how-to-replace-a-hotend-heater-core-one_944862#945415","sourcePhotos":[{"url":"https://help.prusa3d.com/wp-content/uploads/2025/09/eab0eff9ec129209179f0c6cf2b255ac_painted-800x600.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/09/eab0eff9ec129209179f0c6cf2b255ac_painted-800x600.jpeg","credit":["写真：Prusa Research","Photo: Prusa Research","Fotografie: Prusa Research","Foto: Prusa Research"]},{"url":"https://help.prusa3d.com/wp-content/uploads/2025/09/0b5dc324172c7faf_painted-800x600.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/09/0b5dc324172c7faf_painted-800x600.jpeg","credit":["写真：Prusa Research","Photo: Prusa Research","Fotografie: Prusa Research","Foto: Prusa Research"]},{"url":"https://help.prusa3d.com/wp-content/uploads/2025/09/1404d57066bc70d0_painted-800x600.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/09/1404d57066bc70d0_painted-800x600.jpeg","credit":["写真：Prusa Research","Photo: Prusa Research","Fotografie: Prusa Research","Foto: Prusa Research"]}]},{"title":["左カバーを戻す","Refit the left cover","Nasazení levého krytu","Linke Abdeckung montieren"],"body":["配線がはみ出さないよう内側へ収め、カバーの下側を先に掛けます。Nextruder側へ押し込み、配線を挟んでいないことを確認して元のネジで固定します（通常はM3×10、初期型は取り外した2本のM3×10bT）。ベッドの保護材も外します。","Tuck the wires inside without protruding. Hook the cover bottom first, press toward the Nextruder and check for trapped wires. Refit the original fasteners: normally M3×10, or the two removed M3×10bT on early covers. Remove the bed protection.","Vodiče uložte dovnitř bez vyčnívání. Zahákněte spodek krytu, přitlačte k Nextruderu a ověřte, že kabely nejsou skřípnuté. Vraťte původní šrouby: obvykle M3×10, u raných krytů dva sejmuté M3×10bT. Odstraňte ochranu podložky.","Leitungen ohne Überstand innen verstauen. Abdeckung unten einhaken, zum Nextruder drücken und auf eingeklemmte Kabel prüfen. Originalschrauben einsetzen: normalerweise M3×10, bei frühen Abdeckungen die zwei entfernten M3×10bT. Heizbettschutz entfernen."],"refs":[858],"action":"cover-in","componentAccessIndex":14,"id":"heater-945445","officialId":945445,"officialStep":18,"source":"https://help.prusa3d.com/guide/how-to-replace-a-hotend-heater-core-one_944862#945445","sourcePhotos":[{"url":"https://help.prusa3d.com/wp-content/uploads/2025/09/920cc7763734b687_painted-800x600.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/09/920cc7763734b687_painted-800x600.jpeg","credit":["写真：Prusa Research","Photo: Prusa Research","Fotografie: Prusa Research","Foto: Prusa Research"]},{"url":"https://help.prusa3d.com/wp-content/uploads/2025/09/b3c3227b5bdfb86c3f95927475a68db5_painted-800x600.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/09/b3c3227b5bdfb86c3f95927475a68db5_painted-800x600.jpeg","credit":["写真：Prusa Research","Photo: Prusa Research","Fotografie: Prusa Research","Foto: Prusa Research"]},{"url":"https://help.prusa3d.com/wp-content/uploads/2025/09/e957b5b0c5b0155d1239198bbc3f82ec_painted-800x600.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/09/e957b5b0c5b0155d1239198bbc3f82ec_painted-800x600.jpeg","credit":["写真：Prusa Research","Photo: Prusa Research","Fotografie: Prusa Research","Foto: Prusa Research"]}]},{"title":["トップカバーを戻す","Refit the top cover","Nasazení horního krytu","Obere Abdeckung montieren"],"body":["後ろ右と前の切り欠きを合わせ、指定の2か所をナイロンリベットで固定します。","Align rear-right and front recesses; secure the two specified rivet positions.","Zarovnejte pravý zadní roh a přední výřezy; upevněte dva určené nýty.","Hinten rechts und an den vorderen Aussparungen ausrichten; an den zwei vorgesehenen Nietenstellen sichern."],"refs":["top"],"action":"top-in","componentAccessIndex":15,"id":"heater-945507","officialId":945507,"officialStep":19,"source":"https://help.prusa3d.com/guide/how-to-replace-a-hotend-heater-core-one_944862#945507","sourcePhotos":[{"url":"https://help.prusa3d.com/wp-content/uploads/2025/09/79c9482904d96c1a_painted-800x600.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/09/79c9482904d96c1a_painted-800x600.jpeg","credit":["写真：Prusa Research","Photo: Prusa Research","Fotografie: Prusa Research","Foto: Prusa Research"]},{"url":"https://help.prusa3d.com/wp-content/uploads/2025/09/165fd1a9ede0ba87_painted-800x600.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/09/165fd1a9ede0ba87_painted-800x600.jpeg","credit":["写真：Prusa Research","Photo: Prusa Research","Fotografie: Prusa Research","Foto: Prusa Research"]}]},{"title":["電源を戻す","Restore power","Zapnutí napájení","Stromversorgung wiederherstellen"],"body":["ドアを閉じ、電源コードを接続して起動します。","Close the door, reconnect power and switch on.","Zavřete dveře, připojte napájení a zapněte tiskárnu.","Tür schließen, Netzstecker anschließen und einschalten."],"refs":["lcd"],"componentAccessIndex":16,"id":"heater-945551","officialId":945551,"officialStep":20,"source":"https://help.prusa3d.com/guide/how-to-replace-a-hotend-heater-core-one_944862#945551","sourcePhotos":[{"url":"https://help.prusa3d.com/wp-content/uploads/2025/09/0ca0f6cb6cb5b97f_painted-800x600.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/09/0ca0f6cb6cb5b97f_painted-800x600.jpeg","credit":["写真：Prusa Research","Photo: Prusa Research","Fotografie: Prusa Research","Foto: Prusa Research"]},{"url":"https://help.prusa3d.com/wp-content/uploads/2025/09/009b2e30daaf9403_painted-800x600.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/09/009b2e30daaf9403_painted-800x600.jpeg","credit":["写真：Prusa Research","Photo: Prusa Research","Fotografie: Prusa Research","Foto: Prusa Research"]}]},{"title":["ノズル設定を合わせる","Update nozzle settings","Nastavení trysky","Düseneinstellungen anpassen"],"body":["径・種類を変えた場合はSettings → Hardware → Printheadの設定を更新し、ソックの有無も合わせます。径やHF・標準流量を変更した場合は、PrusaSlicerのプリンタープロファイルも実際のノズルに合わせてから印刷を再開します。「画面操作」で実機のファームウェア版に合う経路を確認できます。 この公式ガイドでは、CORE Oneの標準を0.40 mm・High Flowとしています。実際のノズルの径・種類を確認し、変更していなければその設定を保ちます。","If changed, update the Settings → Hardware → Printhead settings for diameter, type and sock. Before printing again, also match the PrusaSlicer printer profile to the actual nozzle diameter and high-flow or standard-flow type. Printer menus shows the route for the firmware on your printer. This guide identifies 0.40 mm High Flow as the CORE One default. Check the actual nozzle diameter and type; keep the existing values if unchanged.","Při změně upravte průměr, typ a návlek v nastavení Settings → Hardware → Printhead. Před dalším tiskem také nastavte profil tiskárny v PrusaSliceru podle skutečného průměru a vysokoprůtokové nebo standardní trysky. V nabídce Menu tiskárny vyberte verzi firmwaru své tiskárny. Tento návod uvádí jako výchozí trysku CORE One 0,40 mm High Flow. Ověřte skutečný průměr a typ; pokud se nezměnily, ponechte nastavení.","Bei Änderungen Durchmesser, Typ und Socke unter Settings → Hardware → Printhead anpassen. Vor dem nächsten Druck auch das PrusaSlicer-Druckerprofil an den tatsächlichen Düsendurchmesser und High-Flow- oder Standardtyp anpassen. Unter Druckermenüs den Pfad für die Firmware des Druckers wählen. Dieser Leitfaden nennt 0,40 mm High Flow als CORE-One-Standard. Tatsächlichen Durchmesser und Typ prüfen; unveränderte Werte beibehalten."],"refs":["lcd"],"firmwareActions":["printhead"],"componentAccessIndex":17,"id":"heater-945587","officialId":945587,"officialStep":21,"source":"https://help.prusa3d.com/guide/how-to-replace-a-hotend-heater-core-one_944862#945587","sourcePhotos":[{"url":"https://help.prusa3d.com/wp-content/uploads/2025/09/37103c344a6dc6ac_painted-800x600.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/09/37103c344a6dc6ac_painted-800x600.jpeg","credit":["写真：Prusa Research","Photo: Prusa Research","Fotografie: Prusa Research","Foto: Prusa Research"]},{"url":"https://help.prusa3d.com/wp-content/uploads/2025/09/53593ef4b0e0e9e8_painted-800x600.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/09/53593ef4b0e0e9e8_painted-800x600.jpeg","credit":["写真：Prusa Research","Photo: Prusa Research","Fotografie: Prusa Research","Foto: Prusa Research"]},{"url":"https://help.prusa3d.com/wp-content/uploads/2025/09/8587c5ce69f636bf_painted-800x600.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/09/8587c5ce69f636bf_painted-800x600.jpeg","credit":["写真：Prusa Research","Photo: Prusa Research","Fotografie: Prusa Research","Foto: Prusa Research"]}]},{"title":["加熱を確認する","Verify heating","Ověření ohřevu","Aufheizen prüfen"],"body":["Control → Temperature → Nozzle Temperatureを200 °C超に設定し、ホーム画面の下部で温度が上がることを確認します。温度が上がらない場合やエラーが出る場合は使用を再開せず、冷却・電源切断後に接続を再確認します。","Set Control → Temperature → Nozzle Temperature above 200 °C. Return to the home screen and check the rising temperature in the bottom bar. If it does not rise or an error appears, do not resume use; cool down and unplug before rechecking connections.","V Control → Temperature → Nozzle Temperature nastavte přes 200 °C. Na hlavní obrazovce ověřte růst teploty ve spodní liště. Pokud neroste nebo se objeví chyba, tisk neobnovujte; před kontrolou spojů nechte vychladnout a odpojte napájení.","Control → Temperature → Nozzle Temperature auf über 200 °C stellen. Auf der Startseite den Temperaturanstieg in der unteren Leiste prüfen. Bei fehlendem Anstieg oder Fehler nicht weiterdrucken; vor der Anschlussprüfung abkühlen lassen und Netzstecker ziehen."],"refs":["lcd","hotend"],"firmwareActions":["heat"],"componentAccessIndex":18,"id":"heater-945657","officialId":945657,"officialStep":22,"source":"https://help.prusa3d.com/guide/how-to-replace-a-hotend-heater-core-one_944862#945657","sourcePhotos":[{"url":"https://help.prusa3d.com/wp-content/uploads/2025/09/e2d5f80290258379_painted-800x600.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/09/e2d5f80290258379_painted-800x600.jpeg","credit":["写真：Prusa Research","Photo: Prusa Research","Fotografie: Prusa Research","Foto: Prusa Research"]},{"url":"https://help.prusa3d.com/wp-content/uploads/2025/09/1624f81f66c9165b_painted-800x600.jpeg","full":"https://help.prusa3d.com/wp-content/uploads/2025/09/1624f81f66c9165b_painted-800x600.jpeg","credit":["写真：Prusa Research","Photo: Prusa Research","Fotografie: Prusa Research","Foto: Prusa Research"]}]}],"heaterService":true};
export function createHeaterReplacementTask(tasks){const current=tasks.find(t=>t.id==='hotend');if(!current)throw Error('Missing standard hotend access procedure');const task=structuredClone(CONTENT);task.accessReference=structuredClone(current);for(const s of task.steps){const access=current.steps[s.componentAccessIndex];if(access?.action)s.action=access.action;if(['cover-out','cover-in'].includes(s.action))s.body=structuredClone(access.body);}return task;}
